using Forjix.Application.Abstractions.Settings;
using Forjix.Application.Features.Settings;
namespace Forjix.Infrastructure.Settings; internal sealed class LocalFileStorage : IFileStorage { private readonly string root = Path.Combine(AppContext.BaseDirectory, "App_Data", "tenant-assets"); public async Task<string> SaveAsync(Guid tenantId, Stream content, string contentType, string extension, CancellationToken ct) { var ext = extension.ToLowerInvariant() switch { ".png" => ".png", ".jpg" or ".jpeg" => ".jpg", ".webp" => ".webp", _ => throw new InvalidOperationException("Unsupported file extension.") }; var folder = Path.Combine(root, tenantId.ToString("N")); Directory.CreateDirectory(folder); var name = $"{Guid.NewGuid():N}{ext}"; await using var target = File.Create(Path.Combine(folder, name)); await content.CopyToAsync(target, ct); return $"{tenantId:N}/{name}"; } public Task<StoredFile?> OpenAsync(string key, CancellationToken ct) { var full = Path.GetFullPath(Path.Combine(root, key.Replace('/', Path.DirectorySeparatorChar))); var safeRoot = Path.GetFullPath(root) + Path.DirectorySeparatorChar; if (!full.StartsWith(safeRoot, StringComparison.OrdinalIgnoreCase) || !File.Exists(full)) return Task.FromResult<StoredFile?>(null); var type = Path.GetExtension(full).ToLowerInvariant() switch { ".png" => "image/png", ".jpg" => "image/jpeg", ".webp" => "image/webp", _ => "application/octet-stream" }; return Task.FromResult<StoredFile?>(new(File.OpenRead(full), type)); } }
